import 'dart:collection';

void main() {
  final graph = {
    'A': ['B', 'C'],
    'B': ['D'],
    'C': ['D'],
    'D': <String>[],
  };
  final q = Queue<String>.from(['A']);
  final seen = {'A'};
  final order = <String>[];
  while (q.isNotEmpty) {
    final n = q.removeFirst();
    order.add(n);
    for (final m in graph[n]!) {
      if (seen.add(m)) q.addLast(m);
    }
  }
  print(order.join());
}
```

